1	package netdiag
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"testing"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/nettrace"
14	)
15	
16	const producerWait = 2 * time.Second
17	
18	// fakeEngine records its calls; no socket, no resolver.
19	type fakeEngine struct {
20		resolveCalls int
21		resolveHost  string
22		resolveCtx   context.Context
23		traceCalls   int
24		traceAddr    netip.Addr
25		traceOpts    nettrace.Options
26		traceCtxErr  error
27	
28		resolveFn func(ctx context.Context, host string) ([]netip.Addr, error)
29		traceFn   func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
30	}
31	
32	func (f *fakeEngine) engine() pathEngine {
33		return pathEngine{
34			supported: func() error { return nil },
35			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
36				f.resolveCalls++
37				f.resolveHost = host
38				f.resolveCtx = ctx
39				if f.resolveFn == nil {
40					return nil, errors.New("unexpected resolve")
41				}
42				return f.resolveFn(ctx, host)
43			},
44			trace: func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
45				f.traceCalls++
46				f.traceAddr = a
47				f.traceOpts = o
48				f.traceCtxErr = ctx.Err()
49				if f.traceFn == nil {
50					return nettrace.Result{Target: a}, nil
51				}
52				return f.traceFn(ctx, a, o, onHop)
53			},
54		}
55	}
56	
57	func hopAt(ttl int) nettrace.Hop {
58		return nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("10.0.0.1")}
59	}
60	
61	// runProducer calls producePath synchronously with nobody reading the
62	// channel, failing if it does not return (the channel capacity must hold).
63	func runProducer(t *testing.T, ctx context.Context, gen int, tg pathTarget, rt time.Duration, e pathEngine) []tea.Msg {
64		t.Helper()
65		out := make(chan tea.Msg, pathChanCap)
66		done := make(chan struct{})
67		go func() {
68			defer close(done)
69			producePath(ctx, gen, tg, rt, e, out)
70		}()
71		select {
72		case <-done:
73		case <-time.After(producerWait):
74			t.Fatal("producePath did not return: the producer blocked")
75		}
76		var msgs []tea.Msg
77		for {
78			select {
79			case m, ok := <-out:
80				if !ok {
81					return msgs
82				}
83				msgs = append(msgs, m)
84			default:
85				t.Fatal("channel not closed after producePath returned")
86				return nil
87			}
88		}
89	}
90	
91	func TestPathChanCapHoldsAWholeTrace(t *testing.T) {
92		if want := nettrace.MaxHopsLimit + 2; pathChanCap != want {
93			t.Fatalf("pathChanCap = %d, want %d", pathChanCap, want)
94		}
95		if pathChanCap != 32 {
96			t.Fatalf("pathChanCap = %d, want 32", pathChanCap)
97		}
98	}
99	
100	func TestProducePathLiteralIPv4SkipsResolve(t *testing.T) {
101		f := &fakeEngine{traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
102			onHop(hopAt(1))
103			onHop(hopAt(2))
104			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeReached, Hops: []nettrace.Hop{hopAt(1), hopAt(2)}}, nil
105		}}
106		msgs := runProducer(t, context.Background(), 7, pathTarget{Host: "1.1.1.1"}, time.Second, f.engine())
107	
108		if f.resolveCalls != 0 {
109			t.Fatalf("resolve called %d times for a literal IPv4", f.resolveCalls)
110		}
111		if f.traceOpts != (nettrace.Options{}) {
112			t.Fatalf("trace options = %+v, want the zero Options", f.traceOpts)
113		}
114		if len(msgs) != 4 {
115			t.Fatalf("got %d messages, want 4 (resolved, 2 hops, done): %#v", len(msgs), msgs)
116		}
117		res, ok := msgs[0].(pathResolvedMsg)
118		if !ok || res.addr != netip.MustParseAddr("1.1.1.1") || res.gen != 7 {
119			t.Fatalf("msgs[0] = %#v, want pathResolvedMsg{7, 1.1.1.1}", msgs[0])
120		}
121		for i, ttl := range []int{1, 2} {
122			h, ok := msgs[1+i].(pathHopMsg)
123			if !ok || h.hop.TTL != ttl || h.gen != 7 {
124				t.Fatalf("msgs[%d] = %#v, want pathHopMsg ttl %d gen 7", 1+i, msgs[1+i], ttl)
125			}
126		}
127		d, ok := msgs[3].(pathDoneMsg)
128		if !ok || d.err != nil || d.gen != 7 || d.result.Outcome != nettrace.OutcomeReached || len(d.result.Hops) != 2 {
129			t.Fatalf("msgs[3] = %#v, want a clean pathDoneMsg", msgs[3])
130		}
131	}
132	
133	func TestProducePathNameResolvesFirstAddress(t *testing.T) {
134		first := netip.MustParseAddr("93.184.216.34")
135		f := &fakeEngine{resolveFn: func(context.Context, string) ([]netip.Addr, error) {
136			return []netip.Addr{first, netip.MustParseAddr("1.2.3.4")}, nil
137		}}
138		msgs := runProducer(t, context.Background(), 1, pathTarget{Host: "example.com", Port: 443}, time.Second, f.engine())
139	
140		if f.resolveCalls != 1 || f.resolveHost != "example.com" {
141			t.Fatalf("resolve calls=%d host=%q, want 1 call for the bare host", f.resolveCalls, f.resolveHost)
142		}
143		if f.traceAddr != first {
144			t.Fatalf("traced %v, want the first address %v", f.traceAddr, first)
145		}
146		res, ok := msgs[0].(pathResolvedMsg)
147		if !ok || res.addr != first {
148			t.Fatalf("msgs[0] = %#v, want pathResolvedMsg{%v}", msgs[0], first)
149		}
150	}
151	
152	func TestProducePathResolveIsBoundedByTheTimeout(t *testing.T) {
153		const timeout = 40 * time.Millisecond
154		f := &fakeEngine{resolveFn: func(ctx context.Context, _ string) ([]netip.Addr, error) {
155			<-ctx.Done() // blocks until the producer's own deadline fires
156			return nil, ctx.Err()
157		}}
158		start := time.Now()
159		msgs := runProducer(t, context.Background(), 1, pathTarget{Host: "slow.example"}, timeout, f.engine())
160	
161		dl, ok := f.resolveCtx.Deadline()
162		if !ok {
163			t.Fatal("resolve context carries no deadline")
164		}
165		if dl.Sub(start) > timeout+producerWait/2 {
166			t.Fatalf("resolve deadline %v after start, want about %v", dl.Sub(start), timeout)
167		}
168		if len(msgs) != 1 {
169			t.Fatalf("got %d messages, want exactly one done: %#v", len(msgs), msgs)
170		}
171		d, ok := msgs[0].(pathDoneMsg)
172		if !ok || !errors.Is(d.err, errPathResolve) {
173			t.Fatalf("msgs[0] = %#v, want pathDoneMsg wrapping errPathResolve", msgs[0])
174		}
175	}
176	
177	func TestProducePathResolveFailureSendsNoHop(t *testing.T) {
178		raw := errors.New("lookup nope.invalid: no such host")
179		f := &fakeEngine{resolveFn: func(context.Context, string) ([]netip.Addr, error) { return nil, raw }}
180		msgs := runProducer(t, context.Background(), 3, pathTarget{Host: "nope.invalid"}, time.Second, f.engine())
181	
182		if f.traceCalls != 0 {
183			t.Fatal("trace ran after a resolution error: a probe would have been sent")
184		}
185		if len(msgs) != 1 {
186			t.Fatalf("got %d messages, want exactly one: %#v", len(msgs), msgs)
187		}
188		d, ok := msgs[0].(pathDoneMsg)
189		if !ok || d.gen != 3 {
190			t.Fatalf("msgs[0] = %#v, want pathDoneMsg gen 3", msgs[0])
191		}
192		if !errors.Is(d.err, errPathResolve) || !errors.Is(d.err, raw) {
193			t.Fatalf("err = %v, want errPathResolve wrapping the resolver error", d.err)
194		}
195		if got, want := pathErrorLabel("nope.invalid", d.err), "Could not resolve nope.invalid — no probe was sent"; got != want {
196			t.Fatalf("label = %q, want %q", got, want)
197		}
198	}
199	
200	func TestProducePathNoAddressIsNoIPv4(t *testing.T) {
201		f := &fakeEngine{resolveFn: func(context.Context, string) ([]netip.Addr, error) { return nil, nil }}
202		msgs := runProducer(t, context.Background(), 1, pathTarget{Host: "v6only.example"}, time.Second, f.engine())
203	
204		if f.traceCalls != 0 || len(msgs) != 1 {
205			t.Fatalf("traceCalls=%d msgs=%#v, want no trace and one done", f.traceCalls, msgs)
206		}
207		d, ok := msgs[0].(pathDoneMsg)
208		if !ok || !errors.Is(d.err, errPathNoIPv4) {
209			t.Fatalf("msgs[0] = %#v, want pathDoneMsg wrapping errPathNoIPv4", msgs[0])
210		}
211	}
212	
213	func TestProducePathTraceErrorIsCarriedByDone(t *testing.T) {
214		wrapped := fmt.Errorf("%w: %w", nettrace.ErrNoRoute, errors.New("network is unreachable"))
215		f := &fakeEngine{traceFn: func(context.Context, netip.Addr, nettrace.Options, func(nettrace.Hop)) (nettrace.Result, error) {
216			return nettrace.Result{}, wrapped
217		}}
218		msgs := runProducer(t, context.Background(), 2, pathTarget{Host: "10.1.2.3"}, time.Second, f.engine())
219	
220		for _, m := range msgs {
221			if _, isHop := m.(pathHopMsg); isHop {
222				t.Fatalf("a hop was sent for a trace that failed to open: %#v", msgs)
223			}
224		}
225		d, ok := msgs[len(msgs)-1].(pathDoneMsg)
226		if !ok || !errors.Is(d.err, nettrace.ErrNoRoute) {
227			t.Fatalf("last = %#v, want pathDoneMsg wrapping ErrNoRoute", msgs[len(msgs)-1])
228		}
229	}
230	
231	func TestProducePathFullTraceNeedsNoReader(t *testing.T) {
232		f := &fakeEngine{traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
233			hops := make([]nettrace.Hop, 0, nettrace.MaxHopsLimit)
234			for ttl := 1; ttl <= nettrace.MaxHopsLimit; ttl++ {
235				onHop(hopAt(ttl))
236				hops = append(hops, hopAt(ttl))
237			}
238			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeMaxHops, Hops: hops}, nil
239		}}
240		// runProducer fails the test if the producer blocks on a full channel.
241		msgs := runProducer(t, context.Background(), 1, pathTarget{Host: "10.9.9.9"}, time.Second, f.engine())
242	
243		if want := nettrace.MaxHopsLimit + 2; len(msgs) != want {
244			t.Fatalf("got %d messages, want %d", len(msgs), want)
245		}
246	}
247	
248	func TestProducePathCanceledBeforeTheCall(t *testing.T) {
249		ctx, cancel := context.WithCancel(context.Background())
250		cancel()
251		f := &fakeEngine{traceFn: func(ctx context.Context, a netip.Addr, _ nettrace.Options, _ func(nettrace.Hop)) (nettrace.Result, error) {
252			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeCancelled}, nil
253		}}
254		msgs := runProducer(t, ctx, 1, pathTarget{Host: "10.0.0.5"}, time.Second, f.engine())
255	
256		if f.traceCalls != 1 || f.traceCtxErr == nil {
257			t.Fatalf("traceCalls=%d ctxErr=%v, want the trace to see the canceled context", f.traceCalls, f.traceCtxErr)
258		}
259		d, ok := msgs[len(msgs)-1].(pathDoneMsg)
260		if !ok || d.result.Outcome != nettrace.OutcomeCancelled {
261			t.Fatalf("last = %#v, want a done with OutcomeCancelled", msgs[len(msgs)-1])
262		}
263	}
264	
265	func TestProducePathCancelMidTraceReturnsWithoutAReader(t *testing.T) {
266		ctx, cancel := context.WithCancel(context.Background())
267		defer cancel()
268		started := make(chan struct{})
269		f := &fakeEngine{traceFn: func(ctx context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
270			onHop(hopAt(1))
271			close(started)
272			<-ctx.Done() // the engine stops on the context only
273			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeCancelled}, nil
274		}}
275		out := make(chan tea.Msg, pathChanCap)
276		done := make(chan struct{})
277		go func() {
278			defer close(done)
279			producePath(ctx, 1, pathTarget{Host: "10.0.0.6"}, time.Second, f.engine(), out)
280		}()
281	
282		select {
283		case <-started:
284		case <-time.After(producerWait):
285			t.Fatal("trace never started")
286		}
287		cancel() // the view cancels, then stops reading: nobody drains out
288		select {
289		case <-done:
290		case <-time.After(producerWait):
291			t.Fatal("producer goroutine still alive after cancel: leaked or blocked")
292		}
293		var last tea.Msg
294		for m := range out { // closed by the producer, so this terminates
295			last = m
296		}
297		if d, ok := last.(pathDoneMsg); !ok || d.result.Outcome != nettrace.OutcomeCancelled {
298			t.Fatalf("last = %#v, want a done with OutcomeCancelled", last)
299		}
300	}
301	
302	func TestProducePathEveryMessageCarriesTheGeneration(t *testing.T) {
303		f := &fakeEngine{
304			resolveFn: func(context.Context, string) ([]netip.Addr, error) {
305				return []netip.Addr{netip.MustParseAddr("9.9.9.9")}, nil
306			},
307			traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
308				onHop(hopAt(1))
309				return nettrace.Result{Target: a}, nil
310			},
311		}
312		const gen = 42
313		msgs := runProducer(t, context.Background(), gen, pathTarget{Host: "dns.example"}, time.Second, f.engine())
314	
315		if len(msgs) != 3 {
316			t.Fatalf("got %d messages, want 3: %#v", len(msgs), msgs)
317		}
318		for i, m := range msgs {
319			var got int
320			switch v := m.(type) {
321			case pathResolvedMsg:
322				got = v.gen
323			case pathHopMsg:
324				got = v.gen
325			case pathDoneMsg:
326				got = v.gen
327			default:
328				t.Fatalf("msgs[%d] has unexpected type %T", i, m)
329			}
330			if got != gen {
331				t.Fatalf("msgs[%d].gen = %d, want %d", i, got, gen)
332			}
333		}
334	}
